"""FM-16AO: differentiated vector geometry challenges."""
import sympy as s
from calibration_bank import L
from calibration_b_bank import make as angle
from calibration_d_bank import make as geometry
from calibration_h_bank import make as dot
TARGETS={('line-plane-angle',6),('perpendicular-parameter',6),('scalar-product',6),('triangle-area',6)}


def revise(path,tier,v):
    if (path,tier) not in TARGETS or v not in (1,2,3): raise ValueError('Not FM-16AO')
    a=s.Integer(v+1); b=a+2; h,k,p,q=s.symbols('h k p q',real=True)
    if path=='line-plane-angle':
        item=angle(path,tier,v); D=1-p*p-q*q; N=a/s.sqrt(D); X=p*N; Z=q*N
        question=f'A line has direction (x,{a},z). Its smaller angles with the planes x=0 and z=0 have sines p and q respectively, where p,q are in [0,1]. For every such pair find all possible (x,z), classify the number of directions and prove completeness.'
        answer=f'No direction if p squared+q squared >= 1. Otherwise x=+/-{L(X)}, z=+/-{L(Z)}, with independent signs. One direction if both sines are zero, two if exactly one is zero, four otherwise.'
        steps=[f'Let N be the positive direction magnitude. The plane-angle formula gives |x|=pN and |z|=qN.',f'Substitution into N squared=x squared+{a*a}+z squared gives N squared times (1-p squared-q squared)={a*a}. Since N is positive, the factor must be strictly positive.',f'Then N={L(N)} and the component magnitudes are {L(X)}, {L(Z)}. Signs are independent because smaller angles ignore orientation.',f'Both sines zero give one direction; exactly one zero gives two; two positive sines give four. All directions are distinct because the fixed second component is positive and equal. Substitution restores both sines, proving sufficiency.']
        facts=[D,N,X,Z,0,1,2,4]; hints=['Use the normals of both planes.','Express both unknown component magnitudes using the same direction magnitude.']; mistake='Treating the two plane angles as independent without checking the common magnitude.'; rationale='Use two plane-angle observations and a shared norm to derive a strict feasibility boundary and sign counts.'
        rub=[('M',1,'Obtain both absolute-component angle relations.'),('R',2,'Use the shared norm to derive the strict feasibility condition, including equality.'),('A',2,'Obtain both component magnitudes and all signs; one mark per component.'),('R',2,'Classify distinct directions and verify sufficiency; one mark each.')]
    elif path=='perpendicular-parameter':
        item=geometry(path,tier,v); R=s.sqrt(a*a-h*h)
        question=f'Let A=(-{a},0,0), B=({a},0,0) and C=(k,h,0), with real h,k. For each h find all k giving a nondegenerate right-angled triangle ABC. Identify the right-angle vertex for every solution, count distinct triangles and prove completeness.'
        answer=f'h=0: none. For h nonzero, k=-{a} at A and k={a} at B. At C, additionally k=+/-{L(R)} when 0<|h|<={a}, counting zero once. Counts: four for 0<|h|<{a}, three for |h|={a}, two for |h|>{a}.'
        steps=[f'If h=0 the points are collinear, so no nondegenerate triangle is possible. Otherwise all three side vectors at each vertex are nonzero.',f'At A the dot product AB dot AC is {2*a}(k+{a}), giving k=-{a}. At B the dot product BA dot BC is {-2*a}(k-{a}), giving k={a}.',f'At C the product CA dot CB is k squared+h squared-{a*a}. Thus k=+/-{L(R)} when |h|<={a}.',f'For h nonzero these C solutions have |k|<{a}, so do not duplicate A or B. There are two, one or zero C solutions as |h| is below, equal to or above {a}. Together with A and B this gives the stated counts.', 'Every right angle must occur at one of the three vertices, and each derived solution satisfies the corresponding zero dot product.']
        facts=[-a,a,R,0,4,3,2]; hints=['Test the dot product of the two sides meeting at each vertex.','Exclude collinear triangles before counting, and check for duplicate k values.']; mistake='Testing only the angle at C, or accepting degenerate triangles when h=0.'; rationale='Compare three distinct vertex orthogonality tests and exclude geometric degeneracy before counting.'
        rub=[('M',1,'Exclude h=0 and formulate vertex dot-product conditions.'),('A',2,'Obtain the A and B branches; one mark each.'),('A',1,'Obtain the C branch with its condition.'),('R',2,'Distinguish all counts and justify disjointness/completeness; one mark each.')]
    elif path=='scalar-product':
        item=dot(path,tier,v); H=4*a/s.sqrt(39); K=s.sqrt(3*h*h-a*a)
        question=f'Let u=(1,0,0), v=(3,4,0) and w=(h,k,{a}). Find every real (h,k) for which the angle between w and u is at most pi/3 and the angle between w and v is at least pi/2. Give the exact lower bound on h, the full interval of k for each admissible h, and prove it is sharp.'
        answer=f'h >= {L(H)}, with -{L(K)} <= k <= -3h/4. The interval is a singleton at the lower bound and nondegenerate above it.'
        steps=[f'All vectors are nonzero. The first angle condition is h/sqrt(h squared+k squared+{a*a}) >= 1/2, so h must be positive before squaring.',f'Squaring gives k squared <= 3h squared-{a*a}. The second angle condition is 3h+4k <= 0, since the positive magnitudes do not affect the sign.',f'Thus k must lie between -{L(K)} and -3h/4. Since h is positive, this interval exists precisely when sqrt(3h squared-{a*a}) >= 3h/4, equivalently 39h squared >= {16*a*a}.',f'The positive lower bound is {L(H)}. At equality the two endpoints coincide; above it the interval has positive length. Every listed pair meets the original unsquared conditions, so the bound is attained and sharp.']
        facts=[H,-K,-3*h/4]; hints=['Convert the angle inequalities to cosine inequalities.','Retain the sign of h before squaring; intersect the two constraints on k.']; mistake='Squaring the first cosine inequality and incorrectly allowing negative h.'; rationale='Intersect two different angular constraints using normalized scalar products and a sharp attained feasibility bound.'
        rub=[('M',1,'Translate both angle inequalities into scalar-product conditions.'),('R',1,'Justify positivity of h before squaring.'),('A',2,'Derive the full interval of k and exact lower bound; one mark each.'),('R',2,'Verify equality and the unsquared conditions, establishing sharpness and completeness.')]
    else:
        item=geometry(path,tier,v); R=s.sqrt(b*b-h*h); T=s.sqrt(b*b-a*a); F=a*s.sqrt(2*h*h+(a-2*R)**2)/2; G=a*s.sqrt(2*h*h+a*a)/2; J=a*s.sqrt(2*h*h+(a+2*R)**2)/2
        question=f'Let A=(0,0,0), B=({a},0,0), C=(0,{a},0), P=(x,y,h). For each real h find all P for which triangles ABP and ACP each have area {L(a*b/2)}. Find the area of BCP for every sign pattern and determine which P minimise and maximise that area, including ties and boundary cases.'
        answer=f'No P if |h|>{b}. Otherwise x,y independently equal +/-{L(R)}. At |h|={b} there is one P with x=y=0. For |h|<{b}, put r={L(R)}: (++): area {L(F)}, mixed: {L(G)}, (--): {L(J)}. The maximum is (--). Minimum: (++) if |h|>{L(T)}, both mixed if |h|<{L(T)}, all three of those sign patterns if equal.'
        steps=[f'Cross products with AB and AC give y squared+h squared={b*b} and x squared+h squared={b*b}. Hence |h|<={b}, and x,y have independent magnitude r={L(R)}. At |h|={b} both vanish.',f'BC cross BP has components ({a}h,{a}h,{a}({a}-x-y)), so the BCP area is {a}/2 times sqrt(2h squared+({a}-x-y) squared).',f'The three sums x+y are 2r,0,-2r, yielding areas {L(F)}, {L(G)}, {L(J)} respectively.',f'For r>0, ({a}+2r) squared exceeds both alternatives, giving the unique maximum (--). The difference between ({a}-2r) squared and {a*a} is 4r(r-{a}). Thus (++) minimises for r<{a}, mixed for r>{a}, and all three patterns tie at r={a}.',f'The threshold r={a} is |h|={L(T)}. At |h|={b} all signs coincide, and the sole point is both minimum and maximum. Every candidate satisfies both given areas, so no other points can qualify.']
        facts=[b,R,T,F,G,J]; hints=['Use the two given areas to constrain the magnitudes of x and y.','Compare squared areas of BCP for the three possible sums x+y.']; mistake='Losing independent signs or assuming the all-positive point always minimises the third area.'; rationale='Reconstruct vertices from two cross-product areas and compare a third area across discrete geometric branches.'
        rub=[('M',2,'Derive both component-square constraints; one mark per area.'),('A',1,'Find all candidate points including the boundary.'),('M',1,'Derive the third area using a cross product or equivalent base-height method.'),('A',1,'Find the three area expressions; follow through consistent component magnitudes.'),('R',2,'Prove maximum and minimum classifications, including ties and the sole-point boundary; one mark each.')]
    item.update(question_latex=question,final_answer_latex=answer,worked_solution_latex=steps,progressive_hints=hints,likely_mistake=mistake,demand_rationale=rationale,facts=[str(s.simplify(f)) for f in facts],rubric=[{'type':t,'marks':m,'criterion':c} for t,m,c in rub]);return item
